"""Q16: add the p0012 S-nucleus temperature robustness results to /output/report.json (idempotent). Usage: python3 -I s75_update_report_q16.py"""
import json
p='/output/report.json'; d=json.load(open(p)); R=d['results']
R[:]=[x for x in R if not x['quantity'].startswith('Q16:')]
d['recipe']=[x for x in d['recipe'] if not x['description'].startswith('Q16:')]
d['datasets']=[x for x in d['datasets'] if x.get('role','')!='Q16 matched elliptical-beam apertures']
A=lambda n,v,u=None:{'name':n,'value':v,**({'unit':u} if u else {})}
common=[A('distance','D=40 Mpc'),A('velocity window','|v-VSYS|<350 km/s, VSYS=2780 km/s, line-free baseline subtracted, same moment-0 recipe as s30'),
 A('team-a inputs','p0012 snapshot /snapshots/team-a-s07 (q1_deblend_ladders_xb4f.csv, dilution.csv, q4c grids Tbg 2.73/5/10 K, q4c_joint.py unchanged except paths) taken as given'),
 A('model','one-zone RADEX LVG, classes A/B/F2 of p0012, flat priors in log n, log N; profile chi2(T) = min over all other parameters; Tbg blackbody, no IR pumping')]
d['datasets'].append({'files':['/data/*Xb55*spw16,18*cube.I.pbcor.fits','/data/*Xb4f*spw16,18*cube.I.pbcor.fits','/data/*Xb47*spw16,18*cube.I.pbcor.fits','/data/*Xb4d*spw25,27*cube (morphology, s71)'],
 'content':'HCN/HCO+ 2-1, 3-2, 4-3 cubes convolved to the Xb4f native 5.72x3.54" PA82 beam (J=3,4) and the Xb55 native 8.64x6.00" PA-90 beam (J=2,3,4); Xb4d 3-2 0.94x0.74" map as core morphology','role':'Q16 matched elliptical-beam apertures'})
d['recipe'].append({'order':len(d['recipe'])+1,'stage':'modelling','description':'Q16: (a) matched ELLIPTICAL-beam T43/T32 and T32/T21 at N, S, Bridge (s72; convolution to the native Xb4f / Xb55 beams, keeps the N-S resolution, response of the other nucleus 0.003 / 0.13); (b) convex-hull consistency of team-a core ladders vs those apertures; (c) forward model with Xb4d 3-2 core templates smoothed to 6.5"/10" (s71, ill-conditioned: reported as a failed deblend, not used); (d) p0012 joint RADEX fit re-run on S and N (s73) for leave-one-out, matched-aperture ladders, ladder errors 14%->25%, Tbg 2.73/5/10 K; (e) tabulation of dchi2(T) (s74)',
 'software':'python3 numpy scipy astropy; p0012 q4c grids (RADEX LVG) from /snapshots/team-a-s07','parameters':[A('common beams','Xb4f native 5.72x3.54 PA82; Xb55 native 8.64x6.00 PA-90'),A('moment window','|v-VSYS|<350 km/s'),A('T grid','10,15,20,25,30,40,50,65,80,100,150 K'),A('Tbg','2.73, 5, 10 K'),A('ladder error','14% (p0012) or 25%; aperture error 3% template + stat')],
 'scripts':['/workspace/scripts/s71_q16_cores.py','/workspace/scripts/s72_q16_native_beams.py','/workspace/scripts/q16_joint_lib.py','/workspace/scripts/s73_q16_Sfit_variants.py','/workspace/scripts/s74_q16_summary.py','/workspace/scripts/s75_update_report_q16.py']})
R.append({'quantity':'Q16: matched-beam 4-3/3-2 and 3-2/2-1 brightness-temperature ratios at the N and S nuclei (elliptical native beams)',
 'target':'N and S nuclear positions (Xb4d peaks), HCN and HCO+, common beams Xb4f 5.72x3.54" (J=3,4) and Xb55 8.64x6.00" (J=2,3,4)',
 'value':'HCN T43/T32: N 0.450+-0.006, S 0.357+-0.011, N/S = 1.26+-0.04 (stat; ~+-0.07 with 5% beam/pointing) in the 5.7x3.5" beam [other-nucleus response 0.003]; Xb55 8.6x6.0" beam: N 0.382, S 0.308 (N/S 1.24; response 0.13). HCO+ T43/T32: N 0.565+-0.005, S 0.486+-0.005 (N/S 1.16+-0.01); Xb55 beam N 0.494, S 0.438 (1.13). T32/T21 (Xb55 beam): HCN N 0.419, S 0.377 (1.11); HCO+ N 0.523, S 0.498 (1.05). Circular smoothing dilutes the contrast: N/S T43/T32 (HCN) 1.26 (5.7x3.5") -> 1.16 (6.5") -> 1.06 (10"). The S/N contrast is detected at >~3.5 sigma (ratio of ratios from the same cubes; absolute band calibration cancels). It maps to an intrinsic N/S ladder contrast >=1.26, i.e. (s63 RADEX mapping) Tk_N/Tk_S >~1.4-3 or n_N/n_S >~2-3. team-a deblended core ladders (HCN 4-3/3-2 N 0.395, S 0.268; HCO+ N 0.482, S 0.442) are 0.06-0.09 BELOW these clean N apertures although the smaller beam should give a higher ratio: the largest value in team-a own component set (N 0.395, Bridge 0.363, Outer 0.28) is below the measured N aperture (0.450), a convex combination cannot exceed it, so the p0012 ladder vector is biased low by >=0.055 (HCN) / >=0.08 (HCO+) unless an unlisted diffuse component has T43/T32>0.45.',
 'uncertainty':'+-0.006 to +-0.011 stat per ratio; +3-5% beam/pointing/template; absolute calibration not cancelled in the individual ratios (10% per band) but cancels in N/S',
 'unit':'ratio of RJ brightness temperatures','assumptions':common,'confidence':'medium',
 'evidence':'s72_q16_native_beams.py -> out/q16/s72.txt, s72.json; s63_beam_dilution.py (out/q3d); team-a q1_deblend_ladders_xb4f.csv (/snapshots/team-a-s07/out/q1/). Why only medium: team-a window/baseline recipe not reproduced; the S aperture includes Bridge (response 0.18 at 2.7") and the outflow lobe.'})
R.append({'quantity':'Q16: robustness of the p0012 result that the S nucleus is cool (Tkin 20-30 K, >=80 K excluded) and N warm (50-100 K)',
 'target':'S and N nuclei at ~1", p0012 joint RADEX fit (8-datum vector) re-run with perturbed ladders; profile chi2(T)',
 'value':'Reproduced p0012: S chi2 min 7.9 at 30 K; dchi2(80 K)=9.3, dchi2(100)=14.4, dchi2(20)=0.9. The exclusion of hot S rests on the two 4-3/3-2 ladder points (leave-one-out of HCN 4-3/3-2: dchi2(80)=5.0; dropping all four ladders: no T constraint, dchi2<4 over 10-150 K) and is not driven by R32/R10/3-2:1-0 or the 3-2/2-1 ladders (replacing the 3-2/2-1 values by our Xb55-beam apertures leaves dchi2(80)=10.5). Replacing the S 4-3/3-2 values by our matched-aperture values (HCN 0.357, HCO+ 0.486; which are upper bounds on neither core): S chi2 min 6.9 at 40 K, dchi2(80)=4.1, dchi2(100)=7.3, dchi2(20)=8.0, allowed (dchi2<4) 30-65 K. All four ladders at aperture values: min 9.3 at 65 K, dchi2<4 = 25-80 K, dchi2(80)=2.7, dchi2(100)=4.5, dchi2(20)=4.9. Midpoint (core,aperture): dchi2(80)=4.9, allowed 20-65 K. Ladder errors 14%->25%: allowed 10-80 K, dchi2(80)=3.6. Tbg=5 K: p0012 vector dchi2(80)=11.2 (allowed 20-40 K); aperture vector dchi2(80)=3.1, dchi2(100)=8.9, allowed 20-80 K. Tbg=10 K is disfavoured for both nuclei (best chi2 rises from 7.9 to 16 (S) and from 19 to 42 (N); best T 20 K; effective 0.24\" beam-averaged Tbg 3.0-3.7 K). N: p0012 vector min 19.3 at 30 K (poor fit); with aperture ladders min 9.1 at 100 K, allowed 65-150 K, dchi2(30)=6.0, dchi2(20)=12.4 (Tbg 5 K: 65-150 K). RESULT: the p0012 S-cool/hot-excluded statement is not robust (it depends on a ladder vector biased low); the data support S Tkin >~25 K (dchi2(20)=4.9-8) and < ~100 K (dchi2(100)=4.5-7.3 at Tbg 2.7, 8.9 at 5 K), N >~50-65 K; N warmer than S is not significant in Tkin (ranges overlap 25-80 K) although N/S excitation differs (previous entry). The central temperature contrast is therefore NOT established as S 20-30 K vs N 50-100 K; a defensible statement is S 25-100 K, N 50-150 K (one-zone, Tbg 2.7-5 K).',
 'uncertainty':'profile-chi2 ranges at dchi2<4 on an 11-point T grid (10-150 K); T-grid resolution 15-30% above 40 K','unit':'K',
 'assumptions':common+[A('aperture ladders','used as stand-in for the core ladders: valid if the non-core gas around S has T43/T32 >= core; tested only through the mid-point and 25% error variants')],'confidence':'medium',
 'evidence':'s73_q16_Sfit_variants.py (copy of team-a q4c_joint.py as q16_joint_lib.py) -> out/q16/s73_*.csv/.log; s74_q16_summary.py -> out/q16/s74.txt (all dchi2 numbers).'})
R.append({'quantity':'Q16: forward-model deblend of the N and S core ladders from circular 6.5"/10" apertures; Tkin>=Tdust and CO checks',
 'target':'N, S, Bridge, E1, E2 positions; Xb4d 3-2 core morphology smoothed to 6.5" and 10"',
 'value':'NOT constraining. A 3-component (N core, S core, rest; and 4-comp with Bridge) linear solution of the observed same-beam T43/T32 gives HCN r_S=0.00 [0.00,0.00] and r_N=0.19-0.22, HCO+ r_S 0.82-0.97 with chi2/dof 3-38 (3% template floor): the N, S, Bridge apertures differ by only 6-14%, the solution is degenerate and hits the non-negativity boundary; r_S is not measured this way (consistent with Q3: circular 10" apertures cannot separate N and S). Implied ladder of the non-core gas if the p0012 core values hold: HCN 0.37-0.43 at 6.5" but 0.27-0.30 at 10" (rc=1-1.5"), i.e. not a constant rest ladder, again pointing to biased core values. Tkin>=Tdust: dust Tb at 0.24" is 0.19 K (N), 0.62 K (S) RJ at 265 GHz (p0012 q2_dust_field, 3.0/3.7 K beam-averaged Tbg,eff) and gives no dust temperature; a mid-IR-heated nucleus with n~1e5 cm-3 is expected to have Tk~Td>~30-40 K (literature, not measured here), at odds with 20-30 K but not with the >=25 K lower edge found above. CO Tb: no CO cube in the data, check not possible. Pereira-Santaella+2024 (2024A&A...681A.117P) find >40 K in the central 100 pc of the S outflow (CO v=1-0 P2/R0, a different phase and region): supports Tk(S)>~40 K, not 20-30 K.',
 'uncertainty':'solutions hit boundary; MC 16-84% over core radius 1-2.5", position +-0.3", floor 3-5%','unit':'ratio','assumptions':common+[A('literature','Pereira-Santaella+2024 A&A 681 A117; Tdust of NGC 3256 nuclei not measured here')],'confidence':'low',
 'evidence':'s71_q16_cores.py -> out/q16/s71.txt; p0012 q2_dust_field.csv'})
d['interpretation']=d['interpretation'].rstrip()+(' Q16 (p0012 S-nucleus temperature): the claim that the S nucleus is cool (20-30 K, >=80 K excluded at dchi2=9) rests on the 4-3/3-2 ladders of the deblended S core (HCN 0.268), which are below the matched-beam apertures we measure at the same nucleus (HCN 0.357, with the N aperture 0.450 vs a team-a N core of 0.395, impossible for a convex combination of their own components). With aperture-based ladders the S fit allows 25-80 K (dchi2(80)=2.7, 100 K=4.5; Tbg 5 K: 100 K disfavoured at 8.9), so S<50 K does NOT survive as a firm statement, and the hot-S exclusion does not either. What does survive is a model-independent excitation contrast: T43/T32 N/S = 1.26+-0.07 (HCN) and 1.16 (HCO+) in the 5.7x3.5" beam (N is more excited), diluted to 1.06 in circular 10" beams, which is why our p0011 could not see it (no conflict: p0011 used circular apertures that mix the nuclei; elliptical native beams keep the N-S resolution). The N/S excitation contrast corresponds to Tk_N/Tk_S >~1.4-3 or n_N/n_S >~2-3 but the absolute S temperature is 25-100 K (one-zone, Tbg 2.7-5 K) and the N 50-150 K. ')
d['caveats'].append('Q16: the matched-aperture ladders are not core ladders; they are upper bounds on neither nuclei (the S aperture includes Bridge at 0.18 response and the outflow lobe). The truth lies between team-a (deblended, apparently biased low) and the apertures; the S Tk range 25-100 K spans both. team-a window/baseline recipe not reproduced, so the origin of their -0.06..-0.09 offset is unknown (possible: velocity window, baseline, deblend NNLS boundary). One-zone RADEX, Tbg blackbody, no IR pumping (HCN 3-2/1-0 pumping failure noted in Q3/Q4) remain. CO, Tdust not measured. A confirmation needs a native-resolution (~1") 4-3 and 2-1 map pair, which the archive does not contain.')
json.dump(d,open(p,'w'),indent=1)
